def caesar_cipher(text, shift):  
    shift %= 26  
    result = []  
    for char in text:  
        if 'a' <= char <= 'z':  
            base = ord('a')  
            shifted_char = chr((ord(char) - base + shift) % 26 + base)  
            result.append(shifted_char)  
        elif 'A' <= char <= 'Z':  
            base = ord('A')  
            shifted_char = chr((ord(char) - base + shift) % 26 + base)  
            result.append(shifted_char)  
        else:  
            result.append(char)  
    return ''.join(result)

def fibonacci(n): 
