def fibonacchi(n: int) -> int:
    """Return the nth Fibonacci number. fibonacci(0)=0 fibonacci(1)=1 fibonacci(n)=fibonacci(n-1)+fibonacci(n-2)"""
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacchi(n-1) + fibonacchi(n-2)

